void hexdump(const void *data, size_t size) {
    const uint8_t *byte_data = (const uint8_t *)data; // 将数据强制转换为字节数组
    size_t i;
    for (i = 0; i < size; i++) {
        // 按16字节一行显示
        if (i % 16 == 0) {
        	rt_kprintf("%08x  ", (unsigned int)i); // 打印偏移地址
        }

        rt_kprintf("%02x ", byte_data[i]); // 打印十六进制数据

        // 每8字节后额外加一个空格
        if ((i + 1) % 8 == 0) {
        	rt_kprintf(" ");
        }

        // 每16字节后换行
        if ((i + 1) % 16 == 0) {
        	rt_kprintf("\n");
        }
    }

    // 如果最后一行不满16字节，补充换行
    if (i % 16 != 0) {
    	rt_kprintf("\n");
    }
}

// 手动实现的 expf 函数（使用 float 类型）
float my_expf(float x)
{
	if(x>4) return 1000;//54.598;
	if(x<-4) return 0.0001;//0.0183;
    float sum = 1.0f;  // e^x 的初始值为 1（对应 0 阶项）
    float term = 1.0f; // 当前项的值，初始值为 1
    int n = 1;
    // 累加 20 项（精度可以根据需要调整）
    for (int i = 1; i <= 20; i++)
    {
        term *= x / n;  // 计算当前项的值
        sum += term;    // 将当前项加入总和
        n++;
    }
    return sum;
}
void my_softmax(struct FloatTensor *result)
{
    float a0 = 0;
    float a1 = 0;
    float a2 = 0;
    float maxv = 0;
    float temp0 = 0;
    float temp1 = 0;
    float temp2 = 0;
    float sum = 0;
    for (int i = 0; i < result->height * result->width * result->channel / 18; i++)
    {
        a0 = result->data_location[i * 18 + 14];
        a1 = result->data_location[i * 18 + 15];
        a2 = result->data_location[i * 18 + 16];

        maxv = a0;
        if (a1 > maxv) maxv = a1;
        if (a2 > maxv) maxv = a2;

        a0 = a0 - maxv;
        a1 = a1 - maxv;
        a2 = a2 - maxv;

        temp0 = my_expf(a0);
        temp1 = my_expf(a1);
        temp2 = my_expf(a2);
        sum = temp0 + temp1 + temp2;

        result->data_location[i * 18 + 14] = temp0 / sum;
        result->data_location[i * 18 + 15] = temp1 / sum;
        result->data_location[i * 18 + 16] = temp2 / sum;

    }
}

