// 将BGR565格式转换为RGB888格式
static void BGR565ToRGB888(uint16_t bgr565, uint8_t *r, uint8_t *g, uint8_t *b)
{
    uint8_t blue  = (bgr565 & 0xF800) >> 11; // 提取蓝色部分（高5位）
    uint8_t green = (bgr565 & 0x07E0) >> 5;  // 提取绿色部分（中间6位）
    uint8_t red   = (bgr565 & 0x001F);       // 提取红色部分（低5位）
    *r = (red << 3) | (red >> 2);            // 5位转换为8位
    *g = (green << 2) | (green >> 4);        // 6位转换为8位
    *b = (blue << 3) | (blue >> 2);          // 5位转换为8位
}

// 裁剪并转换图像
void cropAndConvertImage(const uint16_t *srcImage, uint8_t *dstImage, int srcWidth, int srcHeight, int cropHeight)
{
    int dstWidth = srcWidth;
    int dstHeight = cropHeight;
    for (int y = 0; y < dstHeight; ++y)
    {
        for (int x = 0; x < dstWidth; ++x)
        {
            // 获取原始图像的像素值
            uint16_t bgr565 = srcImage[y * srcWidth + x];
            // 转换为RGB888
            uint8_t r, g, b;
            BGR565ToRGB888(bgr565, &r, &g, &b);
            // 将转换后的值存储到目标图像中
            int dstIndex = (y * dstWidth + x) * 3;
            dstImage[dstIndex + 0] = r;
            dstImage[dstIndex + 1] = g;
            dstImage[dstIndex + 2] = b;
        }
    }
}


FaceRect faces_result[3];
int face_detect(const uint16_t *bgr565_image)
{
    int face_count = objectdetect_cnn(bgr320_buffer1, 160, 120, faces_result);

    return face_count;
}

